import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.BiXHgXAn.js";const c=JSON.parse('{"title":"Conditional execution","description":"Skip optional work with if, enforce requirements with preconditions, and ask for confirmation before execution with prompt.","frontmatter":{"title":"Conditional execution","description":"Skip optional work with if, enforce requirements with preconditions, and ask for confirmation before execution with prompt.","section":"Guide","docType":"guide","outline":"deep"},"headers":[],"relativePath":"docs/guide/conditional-execution.md","filePath":"next/docs/guide/conditional-execution.md"}'),t={name:"docs/guide/conditional-execution.md"};function l(p,s,o,h,d,k){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="conditional-execution" tabindex="-1">Conditional execution <a class="header-anchor" href="#conditional-execution" aria-label="Permalink to &quot;Conditional execution&quot;">​</a></h1><p>Decide what a failed check should mean before choosing a setting: skip optional work, stop with an error, or ask the user whether to continue.</p><table tabindex="0"><thead><tr><th>What do you need?</th><th>Use</th></tr></thead><tbody><tr><td>Skip optional work</td><td><a href="#conditional-execution-with-if"><code>if</code></a></td></tr><tr><td>Stop when a requirement is unmet</td><td><a href="#using-programmatic-checks-to-cancel-the-execution-of-a-task-and-its-dependencies"><code>preconditions</code></a></td></tr><tr><td>Ask before executing commands</td><td><a href="#confirmation-prompts"><code>prompt</code></a></td></tr><tr><td>Skip work already completed</td><td><a href="./up-to-date">Up-to-date checks</a></td></tr></tbody></table><h2 id="conditional-execution-with-if" tabindex="-1">Skip optional work <a class="header-anchor" href="#conditional-execution-with-if" aria-label="Permalink to &quot;Skip optional work {#conditional-execution-with-if}&quot;">​</a></h2><p>An <code>if</code> condition is a shell command. Exit code <code>0</code> allows execution; a non-zero exit code skips the guarded task or command without failing the run.</p><h3 id="task-level-if" tabindex="-1">Skip a whole task <a class="header-anchor" href="#task-level-if" aria-label="Permalink to &quot;Skip a whole task {#task-level-if}&quot;">​</a></h3><p>Use a task-level condition for optional work. This task only runs when a <code>docs/</code> directory exists:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  docs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test -d docs</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &#39;Building documentation&#39;</span></span></code></pre></div><p>Run <code>task docs</code> with and without the directory. If it is absent, Task skips the task and its dependencies. Other tasks in the invocation can continue.</p><h3 id="command-level-if" tabindex="-1">Skip one command <a class="header-anchor" href="#command-level-if" aria-label="Permalink to &quot;Skip one command {#command-level-if}&quot;">​</a></h3><p>Put <code>if</code> on a command when the rest of the task should still run:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &#39;Building documentation&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test -d docs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &#39;Building the application&#39;</span></span></code></pre></div><p><code>task build</code> always prints the application message. It prints the documentation message first only if <code>docs/</code> exists.</p><h3 id="using-templates-in-if-conditions" tabindex="-1">Check a Task variable <a class="header-anchor" href="#using-templates-in-if-conditions" aria-label="Permalink to &quot;Check a Task variable {#using-templates-in-if-conditions}&quot;">​</a></h3><p>Template comparisons produce <code>true</code> or <code>false</code>, which are also shell commands with the corresponding exit codes. Put a configurable default at the root:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">vars</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ENABLE_FEATURE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;false&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  feature</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{eq .ENABLE_FEATURE &quot;true&quot;}}&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &#39;Feature is enabled&#39;</span></span></code></pre></div><p><code>task feature ENABLE_FEATURE=true</code> runs the command. Without that override, Task skips it.</p><h3 id="using-if-with-for-loops" tabindex="-1">Filter loop iterations <a class="header-anchor" href="#using-if-with-for-loops" aria-label="Permalink to &quot;Filter loop iterations {#using-if-with-for-loops}&quot;">​</a></h3><p>A command&#39;s condition is evaluated for each iteration, with that iteration&#39;s values:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  process-items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;a&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;b&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;c&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &quot;processing {{.ITEM}}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[ &quot;{{.ITEM}}&quot; != &quot;b&quot; ]&#39;</span></span></code></pre></div><p>Run <code>task process-items</code> to print <code>processing a</code> and <code>processing c</code>. See <a href="./loops">Loops</a> for the other iteration forms.</p><h2 id="using-programmatic-checks-to-cancel-the-execution-of-a-task-and-its-dependencies" tabindex="-1">Enforce a requirement <a class="header-anchor" href="#using-programmatic-checks-to-cancel-the-execution-of-a-task-and-its-dependencies" aria-label="Permalink to &quot;Enforce a requirement {#using-programmatic-checks-to-cancel-the-execution-of-a-task-and-its-dependencies}&quot;">​</a></h2><p>Use <code>preconditions</code> when missing a requirement should fail the task. Every check must exit with code <code>0</code>. Add <code>msg</code> to explain how to resolve a failure:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  generate-files</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    preconditions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test -f .env</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Create a .env file before generating files.&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mkdir -p directory</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">touch directory/file.txt</span></span></code></pre></div><p><code>task generate-files</code> fails with the message if <code>.env</code> is missing. Create the file and run it again to generate <code>directory/file.txt</code>.</p><p>A plain shell string also works when no custom message is needed. A failed precondition fails tasks that call or depend on this task. Dependencies of the checked task have already run before its preconditions are evaluated; put a check on the task whose commands need protecting.</p><p><code>--force</code> bypasses preconditions as well as up-to-date checks.</p><h3 id="if-vs-preconditions" tabindex="-1">Choose skip or failure <a class="header-anchor" href="#if-vs-preconditions" aria-label="Permalink to &quot;Choose skip or failure {#if-vs-preconditions}&quot;">​</a></h3><p>Use <code>if</code> when skipping is an acceptable result. Use <code>preconditions</code> when a caller should receive an error instead. To require a variable or restrict its allowed values, use <a href="./required-variables">Validation and prompts</a>.</p><h2 id="confirmation-prompts" tabindex="-1">Ask for confirmation <a class="header-anchor" href="#confirmation-prompts" aria-label="Permalink to &quot;Ask for confirmation {#confirmation-prompts}&quot;">​</a></h2><p>Use <code>prompt</code> to ask for approval before a task&#39;s commands run. For example, this task asks before deleting a local build directory:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Remove the local build directory?</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rm -rf build/</span></span></code></pre></div><p>Run <code>task clean</code> in a terminal and answer the confirmation. Declining stops the task with <a href="./../reference/cli#exit-codes">exit code</a> <code>205</code>.</p><p>Unlike <a href="./required-variables#prompting-for-missing-variables-interactively">prompts for missing input</a>, confirmation prompts do not require <code>--interactive</code>. Supplying every required variable does not bypass them.</p><p>For several confirmations, use a list:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Remove the local build directory?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Have you saved everything you need from it?</span></span></code></pre></div><p>Task asks after dependencies have completed and before running <code>cmds</code>. If approval must precede other tasks, call them from <code>cmds</code> in the prompted task instead of listing them as dependencies.</p><p>Use <code>task --yes clean</code> (or <code>task -y clean</code>) to accept automatically. In CI or another environment without a terminal, confirmation fails unless automatic acceptance is enabled.</p><div class="tip custom-block"><p class="custom-block-title">Related guide</p><p><span id="limiting-when-tasks-run"></span></p><p>To control how often a task runs when several tasks call it, use <a href="./dependencies#repeated-calls"><code>run: once</code> or <code>run: when_changed</code></a>. These settings apply within one invocation. Use <a href="./up-to-date">up-to-date checks</a> to skip completed work across invocations.</p></div>`,39)])])}const E=i(t,[["render",l]]);export{c as __pageData,E as default};
